import json,sys,hashlib
from pathlib import Path
tag="p106b_evidence_recovery_v1_s1337";p=Path("HF/sft_ready")/tag/"corpus";r=json.loads((p/"report.json").read_text());rows=[]
for s in r["manifests"]["test_evidence"]["shards"]:rows.extend(json.loads(v) for v in (p/s["path"]).read_text().splitlines())
def sha(v):return hashlib.sha256(json.dumps(v,ensure_ascii=False,sort_keys=True,separators=(",",":")).encode()).hexdigest().upper()
family=sys.argv[1];roots={x["meta"]["neutral_root"] for x in rows if x["meta"]["family"]==family};chosen=min(roots,key=lambda k:sha([tag,"MANUAL_EVIDENCE",k]));events={}
for arm in ("parent","complete_replay","evidence_recovery"):
 q=Path("test_result/evidence/local")/tag/"evaluate"/arm
 events[arm]=[json.loads(v) for v in (q/"evidence_test_000000.jsonl").read_text().splitlines()]
def text(m):return "".join(b["text"] for b in m["content"])
out=[]
for row in rows:
 m=row["meta"]
 if m["neutral_root"]!=chosen:continue
 v=dict(lang=m["language"],condition=m["condition"],enough=m["query_sufficient"],omitted=m["omitted_key"],fields=m["requested_fields"],questions=[text(row["messages"][i]) for i in (0,2,4)],gold=[text(row["messages"][i]) for i in (1,3,5)],actual={})
 for arm,ee in events.items():
  selected=sorted([x for x in ee if x["root"]==m["semantic_root_id"] and x["history"]=="ACTUAL_MODEL"],key=lambda x:x["turn"])
  assert len(selected)==3
  v["actual"][arm]=[x["answer"] for x in selected]
 out.append(v)
print(json.dumps(dict(family=family,neutral=chosen,cases=out),ensure_ascii=False))
